CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_test_users`(
    IN p_scenario VARCHAR(20),
    IN p_password VARCHAR(255)
)
BEGIN
    DECLARE v_total INT DEFAULT 0;
    DECLARE v_i INT DEFAULT 0;
    DECLARE v_user_id INT UNSIGNED;
    DECLARE v_status BIT(1);
    DECLARE v_country CHAR(2);
    DECLARE v_gender VARCHAR(30);
    DECLARE v_age INT;
    DECLARE v_birth_date DATE;
    DECLARE v_given_names VARCHAR(150);
    DECLARE v_family_names VARCHAR(150);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_unique VARCHAR(32);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La contraseña debe tener al menos 8 caracteres';
    END IF;

    CASE p_scenario
        WHEN 'escenario_1' THEN SET v_total = 500;
        WHEN 'escenario_2' THEN SET v_total = 2000;
        WHEN 'escenario_3' THEN SET v_total = 5000;
        ELSE
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Usa escenario_1, escenario_2 o escenario_3';
    END CASE;

    START TRANSACTION;

    WHILE v_i < v_total DO
        SET v_i = v_i + 1;


        IF p_scenario = 'escenario_3' AND v_i > 4000 THEN
            SET v_status = b'0';
        ELSE
            SET v_status = b'1';
        END IF;


        IF p_scenario = 'escenario_1' THEN
            SET v_country = 'US';
        ELSE
            SET v_country = ELT(
                1 + FLOOR(RAND() * 10),
                'MX', 'CA', 'GB', 'FR', 'DE',
                'ES', 'BR', 'JP', 'AU', 'IN'
            );
        END IF;


        IF p_scenario = 'escenario_2' THEN
            SET v_age = 19 + FLOOR(RAND() * 17);
        ELSE
            SET v_age = 18 + FLOOR(RAND() * 48);
        END IF;

        SET v_birth_date = DATE_SUB(CURDATE(), INTERVAL v_age YEAR) - INTERVAL FLOOR(RAND() * 365) DAY;


        SET v_given_names = ELT(
            1 + FLOOR(RAND() * 30),
            'Carlos', 'Maria', 'Jose', 'Ana', 'Luis',
            'Sofia', 'Miguel', 'Lucia', 'Diego', 'Valeria',
            'Daniel', 'Gabriela', 'Alejandro', 'Camila',
            'Fernando', 'Isabella', 'Ricardo', 'Elena',
            'Andres', 'Natalia', 'James', 'Emily',
            'William', 'Olivia', 'Benjamin', 'Charlotte',
            'Noah', 'Amelia', 'Lucas', 'Emma'
        );


        SET v_family_names = ELT(
            1 + FLOOR(RAND() * 30),
            'Hernandez', 'Garcia', 'Martinez', 'Lopez',
            'Gonzalez', 'Rodriguez', 'Perez', 'Sanchez',
            'Ramirez', 'Torres', 'Flores', 'Rivera',
            'Gomez', 'Diaz', 'Cruz', 'Morales',
            'Reyes', 'Ortiz', 'Gutierrez', 'Castillo',
            'Smith', 'Johnson', 'Brown', 'Williams',
            'Jones', 'Miller', 'Davis', 'Wilson',
            'Anderson', 'Taylor'
        );


        IF p_scenario = 'escenario_1' THEN
            SET v_gender = 'Hombre';
        ELSE
            SET v_gender = ELT(
                1 + FLOOR(RAND() * 3),
                'Hombre', 'Mujer', 'Prefiero no decirlo'
            );
        END IF;


        SET v_unique = REPLACE(UUID(), '-', '');
        SET v_email = LOWER(CONCAT(v_given_names, '.', v_family_names, '.', LEFT(v_unique, 8), '@example.com'));
        SET v_nick = LOWER(CONCAT(LEFT(v_given_names, 10), '_', LEFT(v_family_names, 10), '_', LEFT(v_unique, 6)));


        INSERT INTO tb_users (nick, email, password, status, creation_date)
        VALUES (v_nick, v_email, SHA2(p_password, 256), v_status, NOW());

        SET v_user_id = LAST_INSERT_ID();


        INSERT INTO tb_people (user_ID, given_names, family_names, gender, birth_date, country_code, status, creation_date)
        VALUES (v_user_id, v_given_names, v_family_names, v_gender, v_birth_date, v_country, v_status, NOW());

    END WHILE;

    COMMIT;
END

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_restore_product`(
    IN p_product_id INT UNSIGNED
)
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM tb_products
        WHERE id = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;


    IF EXISTS (
        SELECT 1
        FROM tb_products
        WHERE id = p_product_id
          AND status = 'ACTIVE'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra activo';
    END IF;

    UPDATE tb_products
    SET status = 'ACTIVE'
    WHERE id = p_product_id;
END

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_product`(
    IN p_product_id INT UNSIGNED
)
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM tb_products
        WHERE id = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;


    IF EXISTS (
        SELECT 1
        FROM tb_products
        WHERE id = p_product_id
          AND status = 'INACTIVE'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra eliminado';
    END IF;

    UPDATE tb_products
    SET status = 'INACTIVE'
    WHERE id = p_product_id;
END

